# Run manually; never dot-source. No .env reads and no generation/OpenAI.
$ErrorActionPreference='Stop';$code=1
$names=@('APP_ENV','SUPABASE_URL','EDUCATIVO_API_URL','EDUCATIVO_PUBLIC_KEY','EDUCATIVO_A_ID','EDUCATIVO_B_ID','EDUCATIVO_A_TOKEN','EDUCATIVO_B_TOKEN','EDUCATIVO_A_UNIDAD_ID','EDUCATIVO_B_UNIDAD_ID','EDUCATIVO_SYNTHETIC_USERS','EDUCATIVO_LOCAL_API_VERIFIED')
function Set-Private([string]$name,[string]$label){$s=Read-Host $label -AsSecureString;$p=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($s);try{[Environment]::SetEnvironmentVariable($name,[Runtime.InteropServices.Marshal]::PtrToStringBSTR($p),'Process')}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($p);$s.Dispose()}}
try{$env:APP_ENV='test';$env:SUPABASE_URL='https://gwdtlbisykzzplgzczzq.supabase.co';$env:EDUCATIVO_API_URL='http://127.0.0.1:3000';Write-Host 'Educativo IA 03D2B: solo fixtures sinteticos y lecturas API; sin generacion, workers, Storage u OpenAI.';$env:EDUCATIVO_LOCAL_API_VERIFIED=Read-Host 'Backend local verificado contra test: confirmed';$env:EDUCATIVO_SYNTHETIC_USERS=Read-Host 'A/B sinteticos exclusivos: confirmed';Set-Private 'EDUCATIVO_PUBLIC_KEY' 'Clave PUBLICA test';foreach($a in @('A','B')){Set-Private "EDUCATIVO_${a}_ID" "UUID usuario $a";Set-Private "EDUCATIVO_${a}_TOKEN" "Token $a";Set-Private "EDUCATIVO_${a}_UNIDAD_ID" "UUID unidad sintetica propia $a"};& node (Join-Path $PSScriptRoot 'derived-resources-run.js');$code=$LASTEXITCODE}catch{$code=1;Write-Host '03D2B no inicio; revisar guia sin compartir secretos.'}finally{foreach($n in $names){[Environment]::SetEnvironmentVariable($n,$null,'Process')}};exit $code
